<?php require_once __DIR__ . "/../config/config.php"; $conn = @new mysqli(DB_HOST, DB_USER, DB_PASS, DB_NAME); if ($conn->connect_error) die("Connection Failed: " . $conn->connect_error); $queries = ["ALTER TABLE course_materials ADD COLUMN original_filename VARCHAR(255) DEFAULT NULL", "ALTER TABLE assignments ADD COLUMN file_path VARCHAR(255) DEFAULT NULL, ADD COLUMN original_filename VARCHAR(255) DEFAULT NULL", "ALTER TABLE exams ADD COLUMN file_path VARCHAR(255) DEFAULT NULL, ADD COLUMN original_filename VARCHAR(255) DEFAULT NULL", "ALTER TABLE quizzes ADD COLUMN file_path VARCHAR(255) DEFAULT NULL, ADD COLUMN original_filename VARCHAR(255) DEFAULT NULL"]; foreach ($queries as $q) { if ($conn->query($q)) echo "Success: $q\n"; else echo "Error: " . $conn->error . " for query $q\n"; } echo "Migration complete.\n";
